def kpi_card(title, value, subtitle=""):
    return f'''<div class="kpi-card">
        <div class="kpi-title">{title}</div>
        <div class="kpi-value">{value}</div>
        {f'<div class="kpi-subtitle">{subtitle}</div>' if subtitle else ''}
    </div>'''

def section(title, content):
    return f'''<section id="{title.lower().replace(' ','-').replace('&','').replace('—','')}">
    <h2>{title}</h2>
    {content}
</section>'''

def chart_img(key, caption=""):
    return f'''<figure>
    <img src="data:image/png;base64,{charts[key]}" alt="{caption or key}">
    {f'<figcaption>{caption}</figcaption>' if caption else ''}
</figure>'''

def table_from_data(rows, headers):
    thead = "<tr>" + "".join(f"<th>{h}</th>" for h in headers) + "</tr>"
    tbody = ""
    for row in rows:
        tbody += "<tr>" + "".join(f"<td>{cell}</td>" for cell in row) + "</tr>"
    return f"<table><thead>{thead}</thead><tbody>{tbody}</tbody></table>"

